def call(fn,max_attempts):
 for i in range(max_attempts+1):
  try: return fn()
  except Exception: pass
 return None

files.check.py:
from retry import call
calls=[]
def bad(): calls.append(1); raise ValueError('permanent')
try: call(bad,3)
except ValueError: pass
else: raise AssertionError('permanent error swallowed')
assert len(calls)==1
calls.clear()
def transient():
 calls.append(1)
 if len(calls)<3: raise TimeoutError('retry')
 return 42
assert call(transient,3)==42 and len(calls)==3
calls.clear()
try: call(transient,0)
except ValueError: pass
else: raise AssertionError('invalid limit accepted')
assert not calls
print("TESTS_PASS")

